package org.slavicmyths.verify;
import java.util.*;import net.minecraft.world.item.*;import net.minecraft.world.inventory.*;import org.slavicmyths.winters.*;
import static org.slavicmyths.verify.Stabilization269.*;
/** Real vanilla crafting menu/result slot authenticates original; no fabricated receipt issuance. */
final class Winters269 {
 static CraftingMenu menu(boolean copy,ItemStack template){w.setBlock(new net.minecraft.core.BlockPos(1000,200,0),net.minecraft.world.level.block.Blocks.CRAFTING_TABLE.defaultBlockState(),2);var menu=new CraftingMenu(copy?2:1,p.getInventory(),ContainerLevelAccess.create(w,new net.minecraft.core.BlockPos(1000,200,0)));p.containerMenu=menu;var items=WintersRecipe.displayInputs(copy);for(int i=0;i<9;i++)menu.getSlot(i+1).set(copy&&i==4?template.copy():new ItemStack(items[i]));menu.slotsChanged(menu.getSlot(1).container);return menu;}
 static ItemStack take(CraftingMenu menu){var slot=menu.getSlot(0);var out=slot.remove(1);slot.onTake(p,out);return out;}
 static void run(){current="native_winters_result_slot";p.getInventory().clearContent();var originalMenu=menu(false,ItemStack.EMPTY);check(!originalMenu.getSlot(0).getItem().isEmpty(),"real workbench exposes original amulet result");var original=take(originalMenu);check(WintersRecipe.original(original),"real vanilla result slot crafts valid original template");var tag=WintersRecipe.tag(original);check(tag.hasUUID("TwoWintersReceipt")&&WintersTemplates.get(w).contains(tag.getUUID("TwoWintersReceipt")),"actual ItemCraftedEvent authenticates original receipt");for(int i=1;i<=9;i++)check(originalMenu.getSlot(i).getItem().isEmpty(),"native original ingredient slot consumed "+i);originalMenu.removed(p);
 var copyMenu=menu(true,original);check(!copyMenu.getSlot(0).getItem().isEmpty(),"authenticated original unlocks real copy recipe");var copy=take(copyMenu);check(copy.is(WintersContent.AMULET.get())&&!WintersRecipe.original(copy),"copied amulet is functional non-template item");check(ItemStack.isSameItemSameComponents(copyMenu.getSlot(5).getItem(),original)&&copyMenu.getSlot(5).getItem().getCount()==1,"native copy remainder preserves exactly one original template");for(int i=1;i<=9;i++)if(i!=5)check(copyMenu.getSlot(i).getItem().isEmpty(),"native copy ingredient consumed "+i);copyMenu.removed(p);
 var denied=menu(true,copy);check(denied.getSlot(0).getItem().isEmpty(),"real workbench rejects copying non-original copy");denied.removed(p);p.containerMenu=p.inventoryMenu;out.put("additional_recipe_exercised","slavicmyths:two_winters_copy; native CraftingMenu/ResultSlot");}
}
